const PHOTO = '';
const CONFIGS = [
  { label: 'haiku55-5000', body: { model: 'claude-haiku-5-5', max_tokens: 5000 } },
  { label: 'haiku55low-5000', body: { model: 'claude-haiku-5-5', max_tokens: 5000, output_config: { effort: 'low' } } }
];
module.exports = function runModelTest(key, requestAnthropic) {
  const jobs = [];
  for (const photo of [false, true]) for (const c of CONFIGS) for (let run = 1; run <= 3; run++) jobs.push({ c, photo, run });
  const next = i => {
    if (i >= jobs.length) { console.log('MODELTEST done'); return; }
    const j = jobs[i];
    const content = j.photo ? [{ type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: PHOTO } }, { type: 'text', text: PROMPT_PHOTO }] : [{ type: 'text', text: PROMPT_TEXT }];
    const body = Object.assign({ max_tokens: 2500, messages: [{ role: 'user', content }] }, j.c.body);
    const t0 = Date.now();
    requestAnthropic(key, body, (err, status, text) => {
      const ms = Date.now() - t0;
      let o = {}; try { o = JSON.parse(text || '{}'); } catch (e) {}
      const blocks = Array.isArray(o.content) ? o.content : [];
      const answer = (blocks.find(b => b && b.type === 'text') || {}).text || '';
      const head = { id: i, label: j.c.label, photo: j.photo, run: j.run, ms, status, err: err ? String(err.message || err) : '', stop: o.stop_reason || '', usage: o.usage || null, types: blocks.map(b => b.type), error: o.error || null, len: answer.length };
      console.log('MODELTEST head ' + JSON.stringify(head));
      const b64 = Buffer.from(answer, 'utf8').toString('base64');
      for (let k = 0, n = 0; k < b64.length; k += 1200, n++) console.log('MODELTEST part ' + i + ' ' + n + ' ' + b64.slice(k, k + 1200));
      setTimeout(() => next(i + 1), 1500);
    });
  };
  console.log('MODELTEST start ' + jobs.length + ' requests');
  next(0);
};
